import { Component } from '@angular/core';

@Component({
  selector: 'app-root',
  templateUrl: './app.component.html',
  standalone: false,
  styleUrl: './app.component.css'
})
export class AppComponent {
  title = 'alinhamento_front';
}

import { Component, Input } from '@angular/core';
import { DebateContribution } from '../../../../core/models/debate-contribution';

@Component({
  selector: 'app-debate-contribution',
  standalone: false,
  templateUrl: './debate-contribution.component.html',
  styleUrl: './debate-contribution.component.css'
})
export class DebateContributionComponent {
  tie = ""

  @Input()
  debateContribution!: DebateContribution;
  @Input()
  small?: boolean = false;

  showFullText: boolean = false;

  get displayText(): string {
    const text = this.debateContribution.text;
    return this.showFullText || text.length <= 500 ? text : text.slice(0, 500) + '...';
  }

  toggleText(): void {
    this.showFullText = !this.showFullText;
  }

  like() {
    console.log('Like clicked');
  }
}

import { Component, EventEmitter, Input, Output } from '@angular/core';
import { DebateGroup } from '../../../../core/models/debate-group';

@Component({
  selector: 'app-debate-group',
  standalone: false,
  templateUrl: './debate-group.component.html',
  styleUrl: './debate-group.component.css'
})
export class DebateGroupComponent {

  @Input()
  debateGroup?:DebateGroup;

  @Output()
  onSelectDebateGroup = new EventEmitter<Number>();

  onSelectGroup(){
    this.onSelectDebateGroup.emit(this.debateGroup?.id);
  }

}

import { Component } from '@angular/core';

@Component({
  selector: 'app-home',
